_PROFILES = {}
for tier,g,record in _PARAMETER_RECORDS:
    proof=_certificate(record)
    q=proof.factor.value
    profile=Profile(f"dh-v7-tier-{tier}",tier,q.bit_length(),proof.value,q,g,proof)
    _PROFILES[profile.id]=profile


def validate_profile(profile):
    if not isinstance(profile,Profile):
        raise ValueError("Expected a registered DH profile")
    if any(type(v) is not int for v in (profile.instance_size,profile.parameter_bits,profile.p,profile.q,profile.g)):
        raise ValueError("DH parameters must be integers")
    if not 1<=profile.instance_size<=50:
        raise ValueError("Unsupported challenge tier")
    if (profile.p.bit_length()!=_MODULUS_BITS[profile.instance_size-1]
            or profile.parameter_bits!=profile.q.bit_length()
            or profile.certificate.value!=profile.p
            or profile.certificate.factor is None
            or profile.certificate.factor.value!=profile.q
            or _validate_prime_certificate(profile.certificate)!=profile.p):
        raise ValueError("Invalid registered field/subgroup proof")
    if not 1<profile.g<profile.p-1 or pow(profile.g,profile.q,profile.p)!=1:
        raise ValueError("Generator must have prime order q")

@lru_cache(maxsize=len(_PROFILES))
def _profile(profile_id: str) -> Profile:
    if not isinstance(profile_id, str) or profile_id not in _PROFILES:
        raise ValueError("Unknown KEM profile")
    profile = _PROFILES[profile_id]
    validate_profile(profile)
    return profile

def _encode(profile: Profile, value: int) -> bytes:
    return value.to_bytes(profile.width, "big")

def _decode_element(profile: Profile, encoded: bytes) -> int:
    if not isinstance(encoded, bytes) or len(encoded) != profile.width:
        raise ValueError("Group element must use the exact fixed-width byte encoding")
    value = int.from_bytes(encoded, "big")
    if not 1 < value < profile.p - 1 or pow(value, profile.q, profile.p) != 1:
        raise ValueError("Group element must be a nonidentity member of the order-q subgroup")
    return value

def _kdf(profile: Profile, public_key: bytes, ciphertext: bytes, shared: int) -> bytes:
    fields = (
        profile.id.encode("ascii"),
        _encode(profile, profile.p),
        _encode(profile, profile.q),
        _encode(profile, profile.g),
        public_key,
        ciphertext,
        _encode(profile, shared),
    )
    return hashlib.sha256(
        DOMAIN + b"".join(len(field).to_bytes(4, "big") + field for field in fields)
    ).digest()

def exponent_upper_bound(profile):
    """Uniform interval, scoped to the limited model plus a fixed work margin."""
    bits = math.ceil(2 * _INITIAL_ESTIMATES[profile.instance_size]["bits"] + 32)
    return min(profile.q - 1, (1 << bits) - 1)

def _initial_estimate(profile):
    result = dict(_INITIAL_ESTIMATES[profile.instance_size])
    result["bits"] = round(min(result["bits"], math.log2(exponent_upper_bound(profile)) / 2), 6)
    result["model_id"] = INITIAL_SECURITY_MODEL["id"]
    return result

def keygen(profile_id: str) -> tuple[bytes, int]:
    """Return (canonical public-key bytes, private exponent); never persist x publicly."""
    profile = _profile(profile_id)
    private_key = secrets.randbelow(exponent_upper_bound(profile)) + 1
    return _encode(profile, pow(profile.g, private_key, profile.p)), private_key

def encapsulate(profile_id: str, public_key: bytes) -> tuple[bytes, bytes]:
    """Return (canonical ciphertext bytes, complete 32-byte shared-secret target)."""
    profile = _profile(profile_id)
    public_value = _decode_element(profile, public_key)
    ephemeral_exponent = secrets.randbelow(exponent_upper_bound(profile)) + 1
    ciphertext = _encode(profile, pow(profile.g, ephemeral_exponent, profile.p))
    shared = pow(public_value, ephemeral_exponent, profile.p)
    return ciphertext, _kdf(profile, public_key, ciphertext, shared)

def decapsulate(profile_id: str, private_key: int, ciphertext: bytes) -> bytes:
    """Return K, or raise ValueError for invalid input; never expose this as an oracle."""
    profile = _profile(profile_id)
    if type(private_key) is not int or not 1 <= private_key <= exponent_upper_bound(profile):
        raise ValueError("Private exponent must be an integer in the registered [1, M] interval")
    ciphertext_value = _decode_element(profile, ciphertext)
    public_key = _encode(profile, pow(profile.g, private_key, profile.p))
    return _kdf(profile, public_key, ciphertext, pow(ciphertext_value, private_key, profile.p))

def _parameters(profile: Profile) -> dict[str, str]:
    return {**{name: _encode(profile, getattr(profile, name)).hex() for name in ("p", "q", "g")},
            "exponent_upper_bound": hex(exponent_upper_bound(profile))[2:]}

def _encoding(profile: Profile) -> dict[str, Any]:
    return {
        "group_elements": "fixed-width big-endian bytes, lowercase hexadecimal in JSON",
        "group_element_bytes": profile.width,
        "public_key_bytes": profile.width, "ciphertext_bytes": profile.width,
        "shared_secret": "exactly 64 hexadecimal characters (32 complete bytes)",
        "shared_secret_bytes": SHARED_SECRET_BYTES,
    }

def _kdf_spec() -> dict[str, Any]:
    return {
        "hash": "SHA-256",
        "domain_hex": DOMAIN.hex(),
        "framing": "domain || uint32be(len(field)) || field, repeated for each field in order",
        "fields": ["profile_id (ASCII)", "p", "q", "g", "public_key", "ciphertext", "shared_group_element"],
        "integer_encoding": "all integer fields use group_element_bytes, big endian",
    }

def serialize(profile_id: str, public_key: bytes, ciphertext: bytes) -> dict[str, Any]:
    """Build public challenge JSON from an explicit allowlist of public inputs.

    Deliberately does not accept a keypair, secret, or generated-result object.
    This avoids accidental private-key disclosure via a generic serializer.
    """
    profile = _profile(profile_id)
    _decode_element(profile, public_key)
    _decode_element(profile, ciphertext)
    return {
        "scheme_id": SCHEME_ID,
        "version": SCHEME_VERSION,
        "profile_id": profile.id,
        "instance_size": profile.instance_size,
        "modulus_bits": profile.p.bit_length(),
        "initial_security_estimate": _initial_estimate(profile),
        "parameter_bits": profile.parameter_bits,
        "parameters": _parameters(profile),
        "public_key": public_key.hex(),
        "ciphertext": ciphertext.hex(),
        "encoding": _encoding(profile),
        "kdf": _kdf_spec(),
        "implementation_sha256": IMPLEMENTATION_SHA256,
    }

@dataclass(frozen=True, repr=False)
class GeneratedChallenge:
    """Private generation result. Only .public is suitable for client responses."""

    public: dict[str, Any]
    target: bytes
    diagnostics: dict[str, Any]

    def __repr__(self) -> str:
        return "GeneratedChallenge(public=<public inputs>, target=<redacted>, diagnostics=<private>)"

def generate(profile_id: str) -> GeneratedChallenge:
    """Generate once, diagnose once, and preserve Encaps' K even on disagreement.

    No correctness-conditioned retries are performed. Private x and r are not
    returned. Python cannot promise erasure of their temporary in-memory values.
    The caller must store .target confidentially and never serialize this object.
    """
    public_key, private_key = keygen(profile_id)
    ciphertext, target = encapsulate(profile_id, public_key)
    recovered = decapsulate(profile_id, private_key, ciphertext)
    return GeneratedChallenge(
        public=serialize(profile_id, public_key, ciphertext),
        target=target,
        diagnostics={
            "correctness_checked": True,
            "shared_secret_matches": hmac.compare_digest(target, recovered),
            "honest_trials": 1,
            "implementation_sha256": IMPLEMENTATION_SHA256,
        },
    )

def get_manifest(profile_id):
    profile=_profile(profile_id)
    return {
        "id":profile.id,"profile_id":profile.id,"scheme_id":SCHEME_ID,"version":SCHEME_VERSION,
        "name":f"Finite-field Diffie–Hellman · Tier {profile.instance_size}",
        "instance_size":profile.instance_size,"parameter_bits":profile.parameter_bits,
        "parameter_label":"subgroup-order bits","modulus_bits":profile.p.bit_length(),
        "size_parameter":dict(SIZE_PARAMETER),"shared_secret_bytes":SHARED_SECRET_BYTES,
        "initial_security_estimate":_initial_estimate(profile),
        "parameters":_parameters(profile),"encoding":_encoding(profile),"kdf":_kdf_spec(),
        "educational":True,
        "security_claim":"Frozen initial classical rho/NFS reference estimates only. Not a security lower bound, exhaustive best-attack estimate or confidentiality guarantee for this custom KEM.",
        "assumption_context":"Computational Diffie–Hellman in a prime-order subgroup of a prime field. Subgroup discrete logarithms suffice for recovery. The limited reference considers generic rho, the declared interval-search margin, and normalized NFS; it excludes quantum attacks and does not establish a KEM reduction.",
        "distribution":"Fixed public certified p,q,g per tier. Offline public SHAKE sampling with seed crucible/dh-v6/setup/v1/tier-N, recursive Pocklington-certified factors and uniform candidate multipliers, conditioned on exact certificates. Fresh independent x,r uniform in 1..M, M=min(q-1,2^ceil(2*b+32)-1) where b is the frozen reference; this retains about16 interval-DLP reference bits of margin when q permits. The actual interval and subgroup limits are public. Short exponents change the distribution and are not inherited from old receipts. No correctness-conditioned retries. Structured setup is not uniform over all primes.",
        "algorithms":{
            "keygen":"x <- uniform(1..M), M=min(q-1,2^ceil(2*b+32)-1) and b the frozen reference; pk=g^x mod p; sk=x",
            "encapsulate":"r <- uniform(1..M) with the same registered interval rule; c=g^r mod p; K=KDF(profile,p,q,g,pk,c,pk^r mod p)",
            "decapsulate":"validate c; pk=g^sk mod p; K=KDF(profile,p,q,g,pk,c,c^sk mod p)",
        },
        "correctness":{
            "kind":"perfect","failure_bound":"0",
            "argument":"For every admitted p,q,g and honest x,r, (g^x)^r=g^(xr)=(g^r)^x modulo p. Both parties hash identical profile, parameters, public key, ciphertext and fixed-width shared element. Exact prime certificates and generator checks establish prime order q; nonzero x,r pass subgroup/nonidentity checks.",
            "scope":"Every registered tier 1..50 and all honest x,r, under exact arithmetic and deterministic encoding/hashing. This is an algebraic agreement claim, not executable certification or confidentiality.",
            "assumptions":"Exact modular arithmetic, valid recursively proved primes, prime-order generator, and identical deterministic encodings/SHA-256. Collision resistance is not needed for agreement.",
            "evidence_status":"Local reference argument and executable tests; independent review pending.",
            "implementation_checks":"tests/test_classical_frontier.py verifies all certificates, parameter/estimate mapping, honest round trips, input rejection and independent public-input recovery. This is not a test-run attestation.",
        },
        "admission":{"status":"teaching-only","official_ranked":False,"reason":"Local reference challenge; independent correctness/specification and security-estimate review pending."},
        "implementation":{"source":"crucible/dh_v7.py","source_sha256":IMPLEMENTATION_SHA256,"version":SCHEME_VERSION,"runtime":"Python standard library; variable-time integer arithmetic"},
        "references":[
            {"title":"RFC7919 section5.2: rationale for short exponents (not this group specification)","url":"https://www.rfc-editor.org/rfc/rfc7919.html#section-5.2"},
            {"title":"Handbook of Applied Cryptography, chapter 4: Pocklington primality proofs","url":"https://cacr.uwaterloo.ca/hac/about/chap4.pdf"},
            {"title":"NIST SP 800-57 Part 1 Rev. 5 Table 2: conventional 3072-bit/128-bit reference; not approval of this adapter","url":"https://nvlpubs.nist.gov/nistpubs/specialpublications/nist.sp.800-57pt1r5.pdf"},
            {"title":"RFC 7919 A.2: alternative 125-bit estimate for a 3072-bit group","url":"https://www.rfc-editor.org/rfc/rfc7919.html#appendix-A.2"},
        ],
    }


def manifests():
    return [get_manifest(profile_id) for profile_id in _PROFILES]
